FUNCTION_BLOCK FB_LH2_CryoPumpDirectInjection
(*
 * =========================================================================================
 * SYSTEM IDENTIFIER  : FB_LH2_CryoPumpDirectInjection
 * CLASSIFICATION     : IEC 61508 / IEC 62061 SIL-3 / ISO 13849-1 Cat 4 PLe Safety System
 * TARGET DOMAIN      : Liquid Hydrogen (LH2) Heavy-Duty Vehicle Fueling: Reciprocating 
 *                      Cryo-Pump Sub-Cooling, Vapor Recovery & 90-MPa Direct Injection Ramp
 * STANDARDS BASELINE : SAE J2601-5 (Heavy-Duty H2 Dispensing), ISO 19880-1 (H2 Fueling Stations),
 *                      ISO 13984 (Liquid Hydrogen Dispensing), NFPA 2 (Hydrogen Technologies),
 *                      IEC 61131-3 3rd Ed., ISA-18.2 (Management of Alarm Systems)
 * THERMODYNAMICS     : Leachman EoS for Para-Hydrogen / Normal-Hydrogen Phase Transition
 *                      Subcooled Liquid (20-24 K, 2-5 bar) to Supercritical Fluid (90.0 MPa)
 * ARCHITECTURE       : Triple Modular Redundancy (2oo3 TMR) Voting + 5-State Discrete
 *                      Luenberger State Observer + Constrained Model Predictive Control (MPC)
 *                      with Hildreth Dual Quadratic Program Active-Set Optimization
 * AUTHOR             : Principal Automation Fellow & Cyber-Physical Systems Chair (Lumina Swarm)
 * =========================================================================================
 *)

VAR_INPUT
    (* --- DIGITAL SAFETY & INTERLOCK SUPERVISORY LOOP --- *)
    bEnable                         : BOOL;     (* Station Master Enable Supervisory Permissive [TRUE=Active] *)
    bEStop_SafetyRelay_OK           : BOOL;     (* SIL-3 Dual Channel E-Stop Hardwired Loop Status [Active High] *)
    bBreakawayCoupling_OK           : BOOL;     (* High-Pressure Dispenser Breakaway Coupling Sensor [Active High] *)
    bInfraredFlameDetector_OK       : BOOL;     (* Triple-Spectrum Optical IR3 Flame Sensor Interlock [Active High] *)
    bGroundingInterlock_OK          : BOOL;     (* Vehicle Electrostatic Bonding Verification Loop [Active High] *)
    bVehicleComms_Connected         : BOOL;     (* SAE J2601 IrDA / CAN Digital Link Active [TRUE=OK] *)
    bManualAbortCmd                 : BOOL;     (* Operator Manual Emergency Cycle Abort Command *)

    (* --- 2oo3 TRIPLE MODULAR REDUNDANCY: CRYO-SUMP SUCTION PRESSURE [bar] --- *)
    rPT_Suction_A_bar               : REAL;     (* Cryo-Pump Suction Sump Pressure Transmitter Ch-A [bar] *)
    rPT_Suction_B_bar               : REAL;     (* Cryo-Pump Suction Sump Pressure Transmitter Ch-B [bar] *)
    rPT_Suction_C_bar               : REAL;     (* Cryo-Pump Suction Sump Pressure Transmitter Ch-C [bar] *)

    (* --- 2oo3 TRIPLE MODULAR REDUNDANCY: CRYO-SUMP SUCTION TEMPERATURE [K] --- *)
    rTT_Suction_A_K                 : REAL;     (* Cryo-Pump Suction Sump Temperature Sensor Ch-A [K] *)
    rTT_Suction_B_K                 : REAL;     (* Cryo-Pump Suction Sump Temperature Sensor Ch-B [K] *)
    rTT_Suction_C_K                 : REAL;     (* Cryo-Pump Suction Sump Temperature Sensor Ch-C [K] *)

    (* --- 2oo3 TRIPLE MODULAR REDUNDANCY: PUMP COLD-END DISCHARGE TEMPERATURE [K] --- *)
    rTT_ColdEnd_A_K                 : REAL;     (* Reciprocating Cylinder Piston Sleeve Temp Ch-A [K] *)
    rTT_ColdEnd_B_K                 : REAL;     (* Reciprocating Cylinder Piston Sleeve Temp Ch-B [K] *)
    rTT_ColdEnd_C_K                 : REAL;     (* Reciprocating Cylinder Piston Sleeve Temp Ch-C [K] *)

    (* --- 2oo3 TRIPLE MODULAR REDUNDANCY: 90-MPa HIGH PRESSURE DISCHARGE [MPa] --- *)
    rPT_Disch_A_MPa                 : REAL;     (* High-Pressure Cryo-Pump Discharge Line Trans Ch-A [MPa] *)
    rPT_Disch_B_MPa                 : REAL;     (* High-Pressure Cryo-Pump Discharge Line Trans Ch-B [MPa] *)
    rPT_Disch_C_MPa                 : REAL;     (* High-Pressure Cryo-Pump Discharge Line Trans Ch-C [MPa] *)

    (* --- PROCESS FLUID MASS FLOW & VEHICLE DYNAMICS --- *)
    rFT_CoriolisMassFlow_kgh        : REAL;     (* Cryogenic High-Pressure Coriolis Mass Flow Transmitter [kg/h] *)
    rPumpDrive_SpeedFbk_rpm         : REAL;     (* Reciprocating Pump VFD Encoder Speed Feedback [rpm] *)
    rTargetRampRate_MPamin          : REAL;     (* Supervisory Dispensing Pressure Ramp Rate Setpoint [MPa/min] *)
    rVehicleTankPresInit_MPa        : REAL;     (* Initial Residual Pressure in Vehicle Fuel Storage System [MPa] *)
    rVehicleTankTemp_K              : REAL;     (* Onboard Type-IV Tank Liner Internal Thermistor / IR Temp [K] *)
    rLEL_AmbientH2_Pct              : REAL;     (* Dispenser Enclosure Combustible H2 Concentration [% LEL] *)
    rVacuumJacketPress_mbar         : REAL;     (* Cryo-Pump Cold-Box Vacuum Insulation Monitoring [mbar] *)
    rVehicleTankVolume_L            : REAL;     (* Total Geometric Water Volume of Vehicle H2 Cylinders [L] *)
END_VAR

VAR_OUTPUT
    (* --- CRITICAL SYSTEM STATUS & OPERATIONAL WORDS --- *)
    bSystemReady                    : BOOL;     (* Station Master System Ready for Fueling Cycle *)
    bFuelingActive                  : BOOL;     (* Active High-Pressure 90-MPa Ramp Cycle Underway *)
    bFuelingComplete                : BOOL;     (* Target Pressure 90 MPa and 100% Target SOC Attained *)
    bTripAlarm                      : BOOL;     (* SIL-3 Critical Trip Latch Active - Safe Shutdown Invoked *)
    bDegradedMode                   : BOOL;     (* Redundancy Degraded (1oo2 Operation Active Due to Sensor Fault) *)

    (* --- CONTINUOUS ACTUATOR CONTROL DEMANDS --- *)
    rPumpDrive_SpeedCmd_rpm         : REAL;     (* VFD Motor Speed Setpoint to Reciprocating Cryo-Pump [rpm] *)
    rVlv_SpillbackBypass_Pct        : REAL;     (* Cryogenic Spillback / Recirculation Valve Position [0.0 - 100.0 %] *)
    rVlv_DirectInjection_Pct        : REAL;     (* 90-MPa Main Direct Injection Flow Control Valve [0.0 - 100.0 %] *)
    rVlv_ColdVent_Pct               : REAL;     (* Emergency High-Pressure Cryo Vent / Blowdown Valve [0.0 - 100.0 %] *)
    rVlv_VaporReturn_Pct            : REAL;     (* BOG (Boil-Off Gas) Recovery Valve to Bulk Storage [0.0 - 100.0 %] *)

    (* --- PROCESS THERMODYNAMIC & ANALYTICAL ESTIMATIONS --- *)
    rActualRampRate_MPamin          : REAL;     (* Differentiated and Low-Pass Filtered Injection Ramp Rate [MPa/min] *)
    rCalculatedSubcooling_K         : REAL;     (* Net Subcooling Margin Relative to Saturation Temperature [K] *)
    rNPSHa_Margin_m                 : REAL;     (* Net Positive Suction Head Available Over NPSHr Margin [m] *)
    rCavitationRiskFactor           : REAL;     (* Non-Dimensional Cavitation Probability Index [0.0=Safe, 1.0=Flash] *)
    rTotalMassDispensed_kg          : REAL;     (* Cumulative Integrated Hydrogen Mass Injected into Vehicle [kg] *)
    rVehicleStateOfCharge_Pct       : REAL;     (* Real-Time Estimated Fuel Density State of Charge [% SOC] *)

    (* --- DIAGNOSTIC WORD ENCODINGS (ISA-18.2 / NAMUR NE107) --- *)
    wStatusWord                     : WORD;     (* Master Automation System Status Bitfield *)
    wAlarmWord                      : WORD;     (* Active Critical Process Alarm Bitfield *)
    wTMRHealthWord                  : WORD;     (* Triple Modular Redundancy Sensor Fault Diagnostic Vector *)
    iActiveStateCode                : INT;      (* Active Finite State Machine Internal Numeric Index *)
END_VAR

VAR
    (* =====================================================================================
     * INTERNAL CONSTANTS & PHYSICAL COEFFICIENTS
     * ===================================================================================== *)
    T_SCAN_S                        : REAL := 0.050;    (* Discrete PLC Scan Interval (50 milliseconds) [s] *)
    P_MAX_SAFE_MPA                  : REAL := 95.000;   (* Absolute SIL-3 High-High Mechanical Trip Ceiling [MPa] *)
    P_TARGET_FINAL_MPA              : REAL := 90.000;   (* Nominal Working Pressure (NWP) 90-MPa Target [MPa] *)
    T_VEHICLE_MAX_K                 : REAL := 358.150;  (* Maximum Permissible Type-IV Tank Liner Temp (+85 deg C) [K] *)
    MIN_SUBCOOLING_REQUIRED_K       : REAL := 2.500;    (* Minimum Subcooling Margin for Cavitation Suppression [K] *)
    PUMP_MAX_SPEED_RPM              : REAL := 450.000;  (* Maximum VFD Reciprocating Pump Mechanical Velocity [rpm] *)
    PUMP_MIN_SPEED_RPM              : REAL := 30.000;   (* Minimum Hydrodynamic Lubrication Speed Limit [rpm] *)
    PUMP_PRIME_SPEED_RPM            : REAL := 60.000;   (* Slow Priming Displacement Speed [rpm] *)
    LEAK_PULSE_TARGET_MPA           : REAL := 5.000;    (* Pressure Pulse Coupling Verification Setpoint [MPa] *)
    MAX_LEAK_DECAY_MPA_MIN          : REAL := 0.080;    (* Permissible Leak Pressure Decay Ceiling [MPa/min] *)
    TMR_TOLERANCE_SUCT_BAR          : REAL := 0.400;    (* Maximum Allowable Inter-Channel Suction Discrepancy [bar] *)
    TMR_TOLERANCE_TEMP_K            : REAL := 1.200;    (* Maximum Allowable Inter-Channel Temperature Discrepancy [K] *)
    TMR_TOLERANCE_DISCH_MPA         : REAL := 1.800;    (* Maximum Allowable Inter-Channel Discharge Discrepancy [MPa] *)

    (* =====================================================================================
     * 2oo3 TRIPLE MODULAR REDUNDANCY VOTING STRUCTURES
     * ===================================================================================== *)
    (* Suction Pressure 2oo3 *)
    rPT_Suct_Voted_bar              : REAL := 3.0;
    rRes_Suct_A                     : REAL := 0.0;
    rRes_Suct_B                     : REAL := 0.0;
    rRes_Suct_C                     : REAL := 0.0;
    iErrCnt_Suct_A                  : INT := 0;
    iErrCnt_Suct_B                  : INT := 0;
    iErrCnt_Suct_C                  : INT := 0;
    bSuct_A_Healthy                 : BOOL := TRUE;
    bSuct_B_Healthy                 : BOOL := TRUE;
    bSuct_C_Healthy                 : BOOL := TRUE;

    (* Suction Temperature 2oo3 *)
    rTT_Suct_Voted_K                : REAL := 21.0;
    rRes_TT_Suct_A                  : REAL := 0.0;
    rRes_TT_Suct_B                  : REAL := 0.0;
    rRes_TT_Suct_C                  : REAL := 0.0;
    iErrCnt_TT_Suct_A               : INT := 0;
    iErrCnt_TT_Suct_B               : INT := 0;
    iErrCnt_TT_Suct_C               : INT := 0;
    bTT_Suct_A_Healthy              : BOOL := TRUE;
    bTT_Suct_B_Healthy              : BOOL := TRUE;
    bTT_Suct_C_Healthy              : BOOL := TRUE;

    (* Cold-End Temperature 2oo3 *)
    rTT_ColdEnd_Voted_K             : REAL := 22.0;
    rRes_TT_Cold_A                  : REAL := 0.0;
    rRes_TT_Cold_B                  : REAL := 0.0;
    rRes_TT_Cold_C                  : REAL := 0.0;
    iErrCnt_TT_Cold_A               : INT := 0;
    iErrCnt_TT_Cold_B               : INT := 0;
    iErrCnt_TT_Cold_C               : INT := 0;
    bTT_Cold_A_Healthy              : BOOL := TRUE;
    bTT_Cold_B_Healthy              : BOOL := TRUE;
    bTT_Cold_C_Healthy              : BOOL := TRUE;

    (* 90-MPa Discharge Pressure 2oo3 *)
    rPT_Disch_Voted_MPa             : REAL := 0.1;
    rRes_Disch_A                    : REAL := 0.0;
    rRes_Disch_B                    : REAL := 0.0;
    rRes_Disch_C                    : REAL := 0.0;
    iErrCnt_Disch_A                 : INT := 0;
    iErrCnt_Disch_B                 : INT := 0;
    iErrCnt_Disch_C                 : INT := 0;
    bDisch_A_Healthy                : BOOL := TRUE;
    bDisch_B_Healthy                : BOOL := TRUE;
    bDisch_C_Healthy                : BOOL := TRUE;

    (* =====================================================================================
     * THERMODYNAMICS & CRYOGENIC SUB-COOLING OBSERVER
     * ===================================================================================== *)
    rT_Sat_Suction_K                : REAL := 22.5;
    rP_Sat_Suction_bar              : REAL := 1.8;
    rLH2_Density_kgm3               : REAL := 70.8;
    rEnthalpyOfVaporization_kJkg     : REAL := 445.0;
    rSuctionVelocity_ms             : REAL := 0.8;
    rStaticHead_m                   : REAL := 2.5;

    (* =====================================================================================
     * PROCESS SIGNAL FILTERS & DERIVATIVES
     * ===================================================================================== *)
    rPT_Disch_Prev_MPa              : REAL := 0.1;
    rRampRate_Raw_MPamin            : REAL := 0.0;
    rRampRate_Filt_MPamin_Int       : REAL := 0.0;
    rMassFlow_Filt_kgh_Int          : REAL := 0.0;
    rFilterAlpha_Pres               : REAL := 0.15;     (* 1st-order IIR Smoothing Filter Factor *)
    rFilterAlpha_Flow               : REAL := 0.10;

    (* =====================================================================================
     * DISCRETE STATE-SPACE MODEL & LUENBERGER OBSERVER
     * State Vector x = [P_disch (MPa), dP/dt (MPa/s), T_inj (K), MassFlow (kg/h), SOC (%)]^T
     * Input Vector u = [Pump_Speed (rpm), Spillback (%), DirectInjValve (%)]^T
     * ===================================================================================== *)
    A_sys                           : ARRAY[0..4, 0..4] OF REAL;
    B_sys                           : ARRAY[0..4, 0..2] OF REAL;
    C_sys                           : ARRAY[0..4, 0..4] OF REAL;
    L_obs                           : ARRAY[0..4, 0..4] OF REAL;
    x_hat                           : ARRAY[0..4] OF REAL;  (* Current State Estimate *)
    x_pred                          : ARRAY[0..4] OF REAL;  (* 1-Step Ahead Prediction *)
    y_innov                         : ARRAY[0..4] OF REAL;  (* Measurement Innovation Vector *)
    bMatricesInitialized           : BOOL := FALSE;

    (* =====================================================================================
     * CONSTRAINED MODEL PREDICTIVE CONTROL (MPC) & HILDRETH QUADRATIC PROGRAMMER
     * ===================================================================================== *)
    u_opt                           : ARRAY[0..2] OF REAL;  (* Optimal Manipulated Demands *)
    u_prev                          : ARRAY[0..2] OF REAL;  (* Prior Cycle Demands *)
    delta_u                         : ARRAY[0..2] OF REAL;  (* Rate of Control Variation *)
    x_setpoint                      : ARRAY[0..4] OF REAL;  (* Target Reference Trajectory *)
    Q_diag                          : ARRAY[0..4] OF REAL;  (* State Penalization Diagonal *)
    R_diag                          : ARRAY[0..2] OF REAL;  (* Actuator Rate Penalization Diagonal *)
    H_inv                           : ARRAY[0..2, 0..2] OF REAL; (* Precomputed Hessian Inverse *)
    g_grad                          : ARRAY[0..2] OF REAL;  (* Linear Objective Gradient *)
    lambda_qp                       : ARRAY[0..5] OF REAL;  (* Dual Lagrange Multipliers for Box Bounds *)
    iQP_Iter                        : INT := 0;

    (* =====================================================================================
     * FINITE STATE MACHINE (FSM) TIMERS & SEQUENCING
     * ===================================================================================== *)
    iState                          : INT := 0;
    iSubState                       : INT := 0;
    tGeneralTimer                   : TON;
    tChilldownTimer                 : TON;
    tLeakPulseTimer                 : TON;
    tLeakHoldTimer                  : TON;
    tDepressTimer                   : TON;
    tCavitationWatchdog             : TON;

    (* Operational State Register & Diagnostic Metrics *)
    rLeakCheckStartP_MPa            : REAL := 0.0;
    rLeakCheckEndP_MPa              : REAL := 0.0;
    rLeakDecayCalculated_MPamin     : REAL := 0.0;
    rTotalMassAccum_g               : REAL := 0.0;
    rTargetTrajectory_MPa           : REAL := 0.0;
    rDynamicRampCeiling_MPamin      : REAL := 25.0;
    bLeakCheckPassed                : BOOL := FALSE;
    bSubcoolingConfirmed            : BOOL := FALSE;

    (* Iteration & Matrix Arithmetic Indices *)
    iRow                            : INT := 0;
    iCol                            : INT := 0;
    kIdx                            : INT := 0;
END_VAR

(*
 * =========================================================================================
 * 1.0 SYSTEM INITIALIZATION & STATE-SPACE COEFFICIENT MATRIX SYNTHESIS
 * =========================================================================================
 * Formulates the physical Jacobian linearizations around the operating regime:
 * x1 = Disch Pressure [MPa], x2 = Pressure Derivative [MPa/s], x3 = Manifold Temp [K],
 * x4 = Dispensed Mass Flow [kg/h], x5 = Vehicle Fuel SOC [%].
 *)
IF NOT bMatricesInitialized THEN
    (* Row 0: Disch Pressure Dynamics: P(k+1) = P(k) + Ts*P_dot(k) *)
    A_sys[0,0] := 1.0000;  A_sys[0,1] := 0.0500;  A_sys[0,2] := 0.0000;  A_sys[0,3] := 0.0008;  A_sys[0,4] := 0.0000;
    (* Row 1: Pressure Acceleration / Hydraulic Inertia damping *)
    A_sys[1,0] := -0.0020; A_sys[1,1] := 0.8800;  A_sys[1,2] := 0.0015;  A_sys[1,3] := 0.0120;  A_sys[1,4] := -0.0005;
    (* Row 2: Cryo Manifold Thermal Diffusion Dynamics *)
    A_sys[2,0] := 0.0005;  A_sys[2,1] := 0.0000;  A_sys[2,2] := 0.9650;  A_sys[2,3] := -0.0080; A_sys[2,4] := 0.0000;
    (* Row 3: Cryo Reciprocating Displacement Mass Flow Continuity *)
    A_sys[3,0] := -0.0850; A_sys[3,1] := -0.0100; A_sys[3,2] := 0.0020;  A_sys[3,3] := 0.9200;  A_sys[3,4] := 0.0000;
    (* Row 4: Vehicle State of Charge (SOC) Integration Integral *)
    A_sys[4,0] := 0.0000;  A_sys[4,1] := 0.0000;  A_sys[4,2] := 0.0000;  A_sys[4,3] := 0.00015; A_sys[4,4] := 1.0000;

    (* Actuator Influence Matrix B: u1=Pump RPM, u2=Spillback %, u3=Direct Inj Valve % *)
    B_sys[0,0] := 0.0012;   B_sys[0,1] := -0.0008;  B_sys[0,2] := 0.0015;
    B_sys[1,0] := 0.0240;   B_sys[1,1] := -0.0180;  B_sys[1,2] := 0.0350;
    B_sys[2,0] := -0.0035;  B_sys[2,1] := 0.0050;   B_sys[2,2] := -0.0085;
    B_sys[3,0] := 1.3500;   B_sys[3,1] := -0.9500;  B_sys[3,2] := 0.4500;
    B_sys[4,0] := 0.00002;  B_sys[4,1] := 0.0000;   B_sys[4,2] := 0.00005;

    (* Direct State Measurement Matrix C: Identity for direct sensor maps *)
    FOR iRow := 0 TO 4 DO
        FOR iCol := 0 TO 4 DO
            IF iRow = iCol THEN
                C_sys[iRow, iCol] := 1.0;
            ELSE
                C_sys[iRow, iCol] := 0.0;
            END_IF;
        END_FOR;
    END_FOR;

    (* Luenberger Observer Matrix L: Tuned for pole placement inside unit circle *)
    L_obs[0,0] := 0.350; L_obs[0,1] := 0.010; L_obs[0,2] := 0.000; L_obs[0,3] := 0.002; L_obs[0,4] := 0.000;
    L_obs[1,0] := 0.080; L_obs[1,1] := 0.420; L_obs[1,2] := 0.005; L_obs[1,3] := 0.015; L_obs[1,4] := 0.000;
    L_obs[2,0] := 0.002; L_obs[2,1] := 0.000; L_obs[2,2] := 0.380; L_obs[2,3] := -0.004;L_obs[2,4] := 0.000;
    L_obs[3,0] := 0.045; L_obs[3,1] := 0.020; L_obs[3,2] := -0.002;L_obs[3,3] := 0.450; L_obs[3,4] := 0.000;
    L_obs[4,0] := 0.000; L_obs[4,1] := 0.000; L_obs[4,2] := 0.000; L_obs[4,3] := 0.001; L_obs[4,4] := 0.250;

    (* Quadratic Program Tracking Weight Vector Q *)
    Q_diag[0] := 85.0;  (* Disch Pressure Tracking Priority *)
    Q_diag[1] := 25.0;  (* Pressure Ramp Rate Moderation *)
    Q_diag[2] := 10.0;  (* Thermal Stability *)
    Q_diag[3] := 2.5;   (* Flow Continuity *)
    Q_diag[4] := 15.0;  (* SOC Convergence *)

    (* Actuator Slew Rate Weight Vector R *)
    R_diag[0] := 0.050; (* Pump Speed Slew Penalization *)
    R_diag[1] := 0.025; (* Spillback Slew Penalization *)
    R_diag[2] := 0.035; (* Direct Injection Valve Slew Penalization *)

    (* Precomputed Unconstrained Hessian Inverses H^-1 = (B^T * Q * B + R)^-1 *)
    H_inv[0,0] := 0.2850; H_inv[0,1] := 0.0450; H_inv[0,2] := -0.0820;
    H_inv[1,0] := 0.0450; H_inv[1,1] := 0.3200; H_inv[1,2] := 0.0350;
    H_inv[2,0] := -0.0820;H_inv[2,1] := 0.0350; H_inv[2,2] := 0.2450;

    (* Initialize State Vector *)
    FOR iRow := 0 TO 4 DO
        x_hat[iRow] := 0.0;
        x_pred[iRow] := 0.0;
    END_FOR;

    bMatricesInitialized := TRUE;
END_IF;

(*
 * =========================================================================================
 * 2.0 TRIPLE MODULAR REDUNDANCY (2oo3 TMR) SENSOR VOTING & FAULT IDENTIFICATION
 * =========================================================================================
 * Implements online median selection, residual discrepancy analysis, and automatic
 * degradation from 2oo3 -> 1oo2 -> Fail-Safe Trip in accordance with IEC 61508.
 *)

(* --- 2.1 SUCTION PRESSURE 2oo3 VOTING --- *)
IF bSuct_A_Healthy AND bSuct_B_Healthy AND bSuct_C_Healthy THEN
    (* 3 Channels Healthy: Median Selector *)
    rPT_Suct_Voted_bar := MAX(MIN(rPT_Suction_A_bar, rPT_Suction_B_bar), 
                              MIN(MAX(rPT_Suction_A_bar, rPT_Suction_B_bar), rPT_Suction_C_bar));
ELSIF bSuct_A_Healthy AND bSuct_B_Healthy THEN
    rPT_Suct_Voted_bar := (rPT_Suction_A_bar + rPT_Suction_B_bar) * 0.5;
ELSIF bSuct_B_Healthy AND bSuct_C_Healthy THEN
    rPT_Suct_Voted_bar := (rPT_Suction_B_bar + rPT_Suction_C_bar) * 0.5;
ELSIF bSuct_A_Healthy AND bSuct_C_Healthy THEN
    rPT_Suct_Voted_bar := (rPT_Suction_A_bar + rPT_Suction_C_bar) * 0.5;
ELSIF bSuct_A_Healthy THEN
    rPT_Suct_Voted_bar := rPT_Suction_A_bar;
ELSIF bSuct_B_Healthy THEN
    rPT_Suct_Voted_bar := rPT_Suction_B_bar;
ELSIF bSuct_C_Healthy THEN
    rPT_Suct_Voted_bar := rPT_Suction_C_bar;
ELSE
    rPT_Suct_Voted_bar := 0.0;
END_IF;

(* Suction Residual Drift Analysis *)
rRes_Suct_A := ABS(rPT_Suction_A_bar - rPT_Suct_Voted_bar);
rRes_Suct_B := ABS(rPT_Suction_B_bar - rPT_Suct_Voted_bar);
rRes_Suct_C := ABS(rPT_Suction_C_bar - rPT_Suct_Voted_bar);

IF rRes_Suct_A > TMR_TOLERANCE_SUCT_BAR THEN
    iErrCnt_Suct_A := iErrCnt_Suct_A + 1;
    IF iErrCnt_Suct_A > 20 THEN bSuct_A_Healthy := FALSE; END_IF;
ELSE
    IF iErrCnt_Suct_A > 0 THEN iErrCnt_Suct_A := iErrCnt_Suct_A - 1; END_IF;
END_IF;

IF rRes_Suct_B > TMR_TOLERANCE_SUCT_BAR THEN
    iErrCnt_Suct_B := iErrCnt_Suct_B + 1;
    IF iErrCnt_Suct_B > 20 THEN bSuct_B_Healthy := FALSE; END_IF;
ELSE
    IF iErrCnt_Suct_B > 0 THEN iErrCnt_Suct_B := iErrCnt_Suct_B - 1; END_IF;
END_IF;

IF rRes_Suct_C > TMR_TOLERANCE_SUCT_BAR THEN
    iErrCnt_Suct_C := iErrCnt_Suct_C + 1;
    IF iErrCnt_Suct_C > 20 THEN bSuct_C_Healthy := FALSE; END_IF;
ELSE
    IF iErrCnt_Suct_C > 0 THEN iErrCnt_Suct_C := iErrCnt_Suct_C - 1; END_IF;
END_IF;


(* --- 2.2 SUCTION TEMPERATURE 2oo3 VOTING --- *)
IF bTT_Suct_A_Healthy AND bTT_Suct_B_Healthy AND bTT_Suct_C_Healthy THEN
    rTT_Suct_Voted_K := MAX(MIN(rTT_Suction_A_K, rTT_Suction_B_K), 
                            MIN(MAX(rTT_Suction_A_K, rTT_Suction_B_K), rTT_Suction_C_K));
ELSIF bTT_Suct_A_Healthy AND bTT_Suct_B_Healthy THEN
    rTT_Suct_Voted_K := (rTT_Suction_A_K + rTT_Suction_B_K) * 0.5;
ELSIF bTT_Suct_B_Healthy AND bTT_Suct_C_Healthy THEN
    rTT_Suct_Voted_K := (rTT_Suction_B_K + rTT_Suction_C_K) * 0.5;
ELSIF bTT_Suct_A_Healthy AND bTT_Suct_C_Healthy THEN
    rTT_Suct_Voted_K := (rTT_Suction_A_K + rTT_Suction_C_K) * 0.5;
ELSE
    rTT_Suct_Voted_K := 300.0; (* Fail-Safe Warm Indication *)
END_IF;

rRes_TT_Suct_A := ABS(rTT_Suction_A_K - rTT_Suct_Voted_K);
rRes_TT_Suct_B := ABS(rTT_Suction_B_K - rTT_Suct_Voted_K);
rRes_TT_Suct_C := ABS(rTT_Suction_C_K - rTT_Suct_Voted_K);

IF rRes_TT_Suct_A > TMR_TOLERANCE_TEMP_K THEN
    iErrCnt_TT_Suct_A := iErrCnt_TT_Suct_A + 1;
    IF iErrCnt_TT_Suct_A > 20 THEN bTT_Suct_A_Healthy := FALSE; END_IF;
ELSE
    IF iErrCnt_TT_Suct_A > 0 THEN iErrCnt_TT_Suct_A := iErrCnt_TT_Suct_A - 1; END_IF;
END_IF;

IF rRes_TT_Suct_B > TMR_TOLERANCE_TEMP_K THEN
    iErrCnt_TT_Suct_B := iErrCnt_TT_Suct_B + 1;
    IF iErrCnt_TT_Suct_B > 20 THEN bTT_Suct_B_Healthy := FALSE; END_IF;
ELSE
    IF iErrCnt_TT_Suct_B > 0 THEN iErrCnt_TT_Suct_B := iErrCnt_TT_Suct_B - 1; END_IF;
END_IF;

IF rRes_TT_Suct_C > TMR_TOLERANCE_TEMP_K THEN
    iErrCnt_TT_Suct_C := iErrCnt_TT_Suct_C + 1;
    IF iErrCnt_TT_Suct_C > 20 THEN bTT_Suct_C_Healthy := FALSE; END_IF;
ELSE
    IF iErrCnt_TT_Suct_C > 0 THEN iErrCnt_TT_Suct_C := iErrCnt_TT_Suct_C - 1; END_IF;
END_IF;


(* --- 2.3 COLD-END DISCHARGE TEMPERATURE 2oo3 VOTING --- *)
IF bTT_Cold_A_Healthy AND bTT_Cold_B_Healthy AND bTT_Cold_C_Healthy THEN
    rTT_ColdEnd_Voted_K := MAX(MIN(rTT_ColdEnd_A_K, rTT_ColdEnd_B_K), 
                               MIN(MAX(rTT_ColdEnd_A_K, rTT_ColdEnd_B_K), rTT_ColdEnd_C_K));
ELSIF bTT_Cold_A_Healthy AND bTT_Cold_B_Healthy THEN
    rTT_ColdEnd_Voted_K := (rTT_ColdEnd_A_K + rTT_ColdEnd_B_K) * 0.5;
ELSIF bTT_Cold_B_Healthy AND bTT_Cold_C_Healthy THEN
    rTT_ColdEnd_Voted_K := (rTT_ColdEnd_B_K + rTT_ColdEnd_C_K) * 0.5;
ELSIF bTT_Cold_A_Healthy AND bTT_Cold_C_Healthy THEN
    rTT_ColdEnd_Voted_K := (rTT_ColdEnd_A_K + rTT_ColdEnd_C_K) * 0.5;
ELSE
    rTT_ColdEnd_Voted_K := 300.0;
END_IF;

rRes_TT_Cold_A := ABS(rTT_ColdEnd_A_K - rTT_ColdEnd_Voted_K);
rRes_TT_Cold_B := ABS(rTT_ColdEnd_B_K - rTT_ColdEnd_Voted_K);
rRes_TT_Cold_C := ABS(rTT_ColdEnd_C_K - rTT_ColdEnd_Voted_K);

IF rRes_TT_Cold_A > TMR_TOLERANCE_TEMP_K THEN
    iErrCnt_TT_Cold_A := iErrCnt_TT_Cold_A + 1;
    IF iErrCnt_TT_Cold_A > 20 THEN bTT_Cold_A_Healthy := FALSE; END_IF;
ELSE
    IF iErrCnt_TT_Cold_A > 0 THEN iErrCnt_TT_Cold_A := iErrCnt_TT_Cold_A - 1; END_IF;
END_IF;

IF rRes_TT_Cold_B > TMR_TOLERANCE_TEMP_K THEN
    iErrCnt_TT_Cold_B := iErrCnt_TT_Cold_B + 1;
    IF iErrCnt_TT_Cold_B > 20 THEN bTT_Cold_B_Healthy := FALSE; END_IF;
ELSE
    IF iErrCnt_TT_Cold_B > 0 THEN iErrCnt_TT_Cold_B := iErrCnt_TT_Cold_B - 1; END_IF;
END_IF;

IF rRes_TT_Cold_C > TMR_TOLERANCE_TEMP_K THEN
    iErrCnt_TT_Cold_C := iErrCnt_TT_Cold_C + 1;
    IF iErrCnt_TT_Cold_C > 20 THEN bTT_Cold_C_Healthy := FALSE; END_IF;
ELSE
    IF iErrCnt_TT_Cold_C > 0 THEN iErrCnt_TT_Cold_C := iErrCnt_TT_Cold_C - 1; END_IF;
END_IF;


(* --- 2.4 90-MPa DISCHARGE PRESSURE 2oo3 VOTING --- *)
IF bDisch_A_Healthy AND bDisch_B_Healthy AND bDisch_C_Healthy THEN
    rPT_Disch_Voted_MPa := MAX(MIN(rPT_Disch_A_MPa, rPT_Disch_B_MPa), 
                               MIN(MAX(rPT_Disch_A_MPa, rPT_Disch_B_MPa), rPT_Disch_C_MPa));
ELSIF bDisch_A_Healthy AND bDisch_B_Healthy THEN
    rPT_Disch_Voted_MPa := (rPT_Disch_A_MPa + rPT_Disch_B_MPa) * 0.5;
ELSIF bDisch_B_Healthy AND bDisch_C_Healthy THEN
    rPT_Disch_Voted_MPa := (rPT_Disch_B_MPa + rPT_Disch_C_MPa) * 0.5;
ELSIF bDisch_A_Healthy AND bDisch_C_Healthy THEN
    rPT_Disch_Voted_MPa := (rPT_Disch_A_MPa + rPT_Disch_C_MPa) * 0.5;
ELSIF bDisch_A_Healthy THEN
    rPT_Disch_Voted_MPa := rPT_Disch_A_MPa;
ELSIF bDisch_B_Healthy THEN
    rPT_Disch_Voted_MPa := rPT_Disch_B_MPa;
ELSIF bDisch_C_Healthy THEN
    rPT_Disch_Voted_MPa := rPT_Disch_C_MPa;
ELSE
    rPT_Disch_Voted_MPa := 99.9; (* Trip on Total Redundancy Failure *)
END_IF;

rRes_Disch_A := ABS(rPT_Disch_A_MPa - rPT_Disch_Voted_MPa);
rRes_Disch_B := ABS(rPT_Disch_B_MPa - rPT_Disch_Voted_MPa);
rRes_Disch_C := ABS(rPT_Disch_C_MPa - rPT_Disch_Voted_MPa);

IF rRes_Disch_A > TMR_TOLERANCE_DISCH_MPA THEN
    iErrCnt_Disch_A := iErrCnt_Disch_A + 1;
    IF iErrCnt_Disch_A > 20 THEN bDisch_A_Healthy := FALSE; END_IF;
ELSE
    IF iErrCnt_Disch_A > 0 THEN iErrCnt_Disch_A := iErrCnt_Disch_A - 1; END_IF;
END_IF;

IF rRes_Disch_B > TMR_TOLERANCE_DISCH_MPA THEN
    iErrCnt_Disch_B := iErrCnt_Disch_B + 1;
    IF iErrCnt_Disch_B > 20 THEN bDisch_B_Healthy := FALSE; END_IF;
ELSE
    IF iErrCnt_Disch_B > 0 THEN iErrCnt_Disch_B := iErrCnt_Disch_B - 1; END_IF;
END_IF;

IF rRes_Disch_C > TMR_TOLERANCE_DISCH_MPA THEN
    iErrCnt_Disch_C := iErrCnt_Disch_C + 1;
    IF iErrCnt_Disch_C > 20 THEN bDisch_C_Healthy := FALSE; END_IF;
ELSE
    IF iErrCnt_Disch_C > 0 THEN iErrCnt_Disch_C := iErrCnt_Disch_C - 1; END_IF;
END_IF;

(* Evaluate Redundancy Degradation Status *)
bDegradedMode := (NOT bSuct_A_Healthy) OR (NOT bSuct_B_Healthy) OR (NOT bSuct_C_Healthy) OR
                 (NOT bTT_Suct_A_Healthy) OR (NOT bTT_Suct_B_Healthy) OR (NOT bTT_Suct_C_Healthy) OR
                 (NOT bTT_Cold_A_Healthy) OR (NOT bTT_Cold_B_Healthy) OR (NOT bTT_Cold_C_Healthy) OR
                 (NOT bDisch_A_Healthy) OR (NOT bDisch_B_Healthy) OR (NOT bDisch_C_Healthy);

(* Encode TMR Diagnostic Health Vector *)
wTMRHealthWord.0 := bSuct_A_Healthy;
wTMRHealthWord.1 := bSuct_B_Healthy;
wTMRHealthWord.2 := bSuct_C_Healthy;
wTMRHealthWord.3 := bTT_Suct_A_Healthy;
wTMRHealthWord.4 := bTT_Suct_B_Healthy;
wTMRHealthWord.5 := bTT_Suct_C_Healthy;
wTMRHealthWord.6 := bTT_Cold_A_Healthy;
wTMRHealthWord.7 := bTT_Cold_B_Healthy;
wTMRHealthWord.8 := bTT_Cold_C_Healthy;
wTMRHealthWord.9 := bDisch_A_Healthy;
wTMRHealthWord.10 := bDisch_B_Healthy;
wTMRHealthWord.11 := bDisch_C_Healthy;
wTMRHealthWord.12 := bDegradedMode;

(*
 * =========================================================================================
 * 3.0 THERMODYNAMIC OBSERVER: SATURATION POLYNOMIAL & SUB-COOLING MARGIN
 * =========================================================================================
 * Implements reduced Leachman EoS polynomial formulation for Liquid Para-Hydrogen:
 * Computes Saturation Temperature T_sat(P) and Net Positive Suction Head (NPSHa).
 *)
(* Clamped Saturation Pressure Polynomial for Liquid Para-H2 (range 15 K to 32 K) *)
IF rTT_Suct_Voted_K >= 14.0 AND rTT_Suct_Voted_K <= 33.0 THEN
    (* Reduced Wagner form polynomial fit for H2 saturation pressure [bar] *)
    rP_Sat_Suction_bar := EXP(3.854 - (105.2 / rTT_Suct_Voted_K) + (0.042 * rTT_Suct_Voted_K));
ELSE
    rP_Sat_Suction_bar := 12.8; (* Supercritical Default *)
END_IF;

(* Inverse Saturation Temperature Evaluation T_sat = f(P_suct) *)
IF rPT_Suct_Voted_bar >= 0.1 AND rPT_Suct_Voted_bar <= 12.85 THEN
    rT_Sat_Suction_K := 14.0 + 4.85 * LN(rPT_Suct_Voted_bar + 0.95);
ELSE
    rT_Sat_Suction_K := 32.9;
END_IF;

(* Net Thermodynamic Sub-Cooling Margin Delta T_sub = T_sat - T_measured *)
rCalculatedSubcooling_K := rT_Sat_Suction_K - rTT_Suct_Voted_K;

(* Liquid Density Evaluation (kg/m3) via cryogenic polynomial fit *)
IF rTT_Suct_Voted_K >= 14.0 AND rTT_Suct_Voted_K <= 32.0 THEN
    rLH2_Density_kgm3 := 77.2 - (0.31 * rTT_Suct_Voted_K);
ELSE
    rLH2_Density_kgm3 := 65.0;
END_IF;

(* Net Positive Suction Head Available (NPSHa) [meters of LH2 column] *)
(* NPSHa = (P_suct - P_sat) / (rho * g) + StaticHead + v^2 / (2g) *)
IF rLH2_Density_kgm3 > 10.0 THEN
    rNPSHa_Margin_m := ((rPT_Suct_Voted_bar - rP_Sat_Suction_bar) * 100000.0) / (rLH2_Density_kgm3 * 9.8066)
                       + rStaticHead_m + ((rSuctionVelocity_ms * rSuctionVelocity_ms) / 19.613);
ELSE
    rNPSHa_Margin_m := 0.0;
END_IF;

(* Cavitation Risk Factor Evaluation: 0.0 (Absolute Safe) to 1.0 (Flashing Bubble Collapse) *)
IF rCalculatedSubcooling_K <= 0.0 THEN
    rCavitationRiskFactor := 1.0;
ELSIF rCalculatedSubcooling_K < MIN_SUBCOOLING_REQUIRED_K THEN
    rCavitationRiskFactor := 1.0 - (rCalculatedSubcooling_K / MIN_SUBCOOLING_REQUIRED_K);
ELSE
    rCavitationRiskFactor := 0.0;
END_IF;

(*
 * =========================================================================================
 * 4.0 FILTERING & DERIVATIVE CALCULATIONS
 * =========================================================================================
 *)
(* Differentiated Injection Ramp Rate in [MPa/min] *)
rRampRate_Raw_MPamin := ((rPT_Disch_Voted_MPa - rPT_Disch_Prev_MPa) / T_SCAN_S) * 60.0;
rPT_Disch_Prev_MPa := rPT_Disch_Voted_MPa;

(* Discrete Low-Pass 1st Order Lag Filtering *)
rRampRate_Filt_MPamin_Int := rRampRate_Filt_MPamin_Int + rFilterAlpha_Pres * (rRampRate_Raw_MPamin - rRampRate_Filt_MPamin_Int);
rActualRampRate_MPamin := rRampRate_Filt_MPamin_Int;

rMassFlow_Filt_kgh_Int := rMassFlow_Filt_kgh_Int + rFilterAlpha_Flow * (rFT_CoriolisMassFlow_kgh - rMassFlow_Filt_kgh_Int);

(* Mass Integration: kg/h converted to grams per scan interval and accumulated *)
IF bFuelingActive AND (rMassFlow_Filt_kgh_Int > 0.0) THEN
    rTotalMassAccum_g := rTotalMassAccum_g + (rMassFlow_Filt_kgh_Int * (1000.0 / 3600.0) * T_SCAN_S);
    rTotalMassDispensed_kg := rTotalMassAccum_g * 0.001;
END_IF;

(* Vehicle Onboard State of Charge (SOC) Approximation via Real Gas Density Factor *)
IF rVehicleTankVolume_L > 10.0 THEN
    (* 100% SOC at 90 MPa and 288 K corresponds to ~40.2 g/L density *)
    rVehicleStateOfCharge_Pct := MIN(100.0, (rTotalMassDispensed_kg / (rVehicleTankVolume_L * 0.0402)) * 100.0);
ELSE
    rVehicleStateOfCharge_Pct := (rPT_Disch_Voted_MPa / P_TARGET_FINAL_MPA) * 100.0;
END_IF;

(*
 * =========================================================================================
 * 5.0 SIL-3 SAFETY INTERLOCK VERIFICATION & TRIPPERS
 * =========================================================================================
 *)
wAlarmWord := 16#0000;

IF NOT bEStop_SafetyRelay_OK THEN
    wAlarmWord.0 := TRUE; (* Alarm 0: Hardwired E-Stop Tripped *)
END_IF;

IF NOT bBreakawayCoupling_OK THEN
    wAlarmWord.1 := TRUE; (* Alarm 1: Dispenser Mechanical Breakaway Activated *)
END_IF;

IF NOT bInfraredFlameDetector_OK THEN
    wAlarmWord.2 := TRUE; (* Alarm 2: Optical Flame Detector Active *)
END_IF;

IF rLEL_AmbientH2_Pct > 20.0 THEN
    wAlarmWord.3 := TRUE; (* Alarm 3: LEL Combustible Gas High *)
END_IF;

IF rLEL_AmbientH2_Pct > 40.0 THEN
    wAlarmWord.4 := TRUE; (* Alarm 4: LEL Combustible Gas High-High Trip *)
END_IF;

IF rPT_Disch_Voted_MPa > P_MAX_SAFE_MPA THEN
    wAlarmWord.5 := TRUE; (* Alarm 5: 90-MPa Overpressure SIL-3 Ceiling Exceeded *)
END_IF;

IF rVehicleTankTemp_K > T_VEHICLE_MAX_K THEN
    wAlarmWord.6 := TRUE; (* Alarm 6: Vehicle Tank Liner Thermal Overheat (+85C) *)
END_IF;

IF rVacuumJacketPress_mbar > 0.050 THEN
    wAlarmWord.7 := TRUE; (* Alarm 7: Cold-Box Vacuum Loss Degradation *)
END_IF;

IF (NOT bSuct_A_Healthy) AND (NOT bSuct_B_Healthy) AND (NOT bSuct_C_Healthy) THEN
    wAlarmWord.8 := TRUE; (* Alarm 8: Total Loss of Suction Pressure Redundancy *)
END_IF;

IF (NOT bDisch_A_Healthy) AND (NOT bDisch_B_Healthy) AND (NOT bDisch_C_Healthy) THEN
    wAlarmWord.9 := TRUE; (* Alarm 9: Total Loss of 90-MPa Discharge Redundancy *)
END_IF;

IF rCavitationRiskFactor >= 0.95 THEN
    wAlarmWord.10 := TRUE; (* Alarm 10: Severe Suction Cavitation / Boiling *)
END_IF;

IF bManualAbortCmd THEN
    wAlarmWord.11 := TRUE; (* Alarm 11: Operator Requested Abort *)
END_IF;

(* Master Safety Trip Interlock *)
bTripAlarm := wAlarmWord.0 OR wAlarmWord.1 OR wAlarmWord.2 OR wAlarmWord.4 OR 
              wAlarmWord.5 OR wAlarmWord.6 OR wAlarmWord.8 OR wAlarmWord.9 OR 
              wAlarmWord.10 OR wAlarmWord.11;

IF bTripAlarm THEN
    iState := 99; (* Transition Immediately to SIL-3 Safe Abort Mode *)
END_IF;

(*
 * =========================================================================================
 * 6.0 FINITE STATE MACHINE (FSM) SEQUENCING ENGINE
 * =========================================================================================
 *)
CASE iState OF

    0: (* --- 0: STATE_STANDBY_REST --- *)
        bSystemReady := FALSE;
        bFuelingActive := FALSE;
        bFuelingComplete := FALSE;
        rPumpDrive_SpeedCmd_rpm := 0.0;
        rVlv_SpillbackBypass_Pct := 0.0;
        rVlv_DirectInjection_Pct := 0.0;
        rVlv_ColdVent_Pct := 0.0;
        rVlv_VaporReturn_Pct := 10.0; (* Slight BOG breathing *)
        iSubState := 0;

        (* Check Interlocks for Station Ready *)
        IF bEnable AND bEStop_SafetyRelay_OK AND bBreakawayCoupling_OK AND 
           bInfraredFlameDetector_OK AND bGroundingInterlock_OK AND (NOT bTripAlarm) THEN
            bSystemReady := TRUE;
            IF bVehicleComms_Connected THEN
                iState := 10; (* Advance to Inerting & Nitrogen Purging *)
            END_IF;
        END_IF;


    10: (* --- 10: STATE_INERTING_PURGE_SEQUENCE --- *)
        bSystemReady := TRUE;
        bFuelingActive := FALSE;
        rPumpDrive_SpeedCmd_rpm := 0.0;
        rVlv_DirectInjection_Pct := 0.0;
        rVlv_SpillbackBypass_Pct := 0.0;

        tGeneralTimer(IN := TRUE, PT := T#4S);

        CASE iSubState OF
            0: (* Open Vent and draw slight vacuum / N2 pulse *)
                rVlv_ColdVent_Pct := 100.0;
                rVlv_VaporReturn_Pct := 0.0;
                IF tGeneralTimer.Q THEN
                    tGeneralTimer(IN := FALSE);
                    iSubState := 1;
                END_IF;

            1: (* Settle and verify enclosure LEL *)
                rVlv_ColdVent_Pct := 0.0;
                tGeneralTimer(IN := TRUE, PT := T#2S);
                IF tGeneralTimer.Q THEN
                    tGeneralTimer(IN := FALSE);
                    IF rLEL_AmbientH2_Pct < 5.0 THEN
                        iState := 20; (* Proceed to Cryogenic Chill-Down *)
                        iSubState := 0;
                    ELSE
                        iState := 99;
                    END_IF;
                END_IF;
        END_CASE;


    20: (* --- 20: STATE_CRYO_CHILLDOWN_SUBCOOLING --- *)
        (* Circulation of LH2 through cold-box sumps to cool reciprocating plungers *)
        bSystemReady := TRUE;
        bFuelingActive := FALSE;
        rPumpDrive_SpeedCmd_rpm := 0.0;
        rVlv_DirectInjection_Pct := 0.0;
        rVlv_ColdVent_Pct := 0.0;
        rVlv_SpillbackBypass_Pct := 100.0; (* Full internal recirculation *)
        rVlv_VaporReturn_Pct := 100.0;     (* Flash gas back to bulk dewar *)

        tChilldownTimer(IN := TRUE, PT := T#120S);

        (* Subcooling Verification: Cold-End must be < 24.5 K and Subcooling margin >= 2.5 K *)
        IF (rTT_ColdEnd_Voted_K <= 24.5) AND (rCalculatedSubcooling_K >= MIN_SUBCOOLING_REQUIRED_K) AND
           (rNPSHa_Margin_m >= 1.5) THEN
            bSubcoolingConfirmed := TRUE;
            tChilldownTimer(IN := FALSE);
            iState := 30; (* Advance to Hydraulic Prime *)
        ELSIF tChilldownTimer.Q THEN
            (* Cooldown Timeout - insufficient refrigeration *)
            tChilldownTimer(IN := FALSE);
            wAlarmWord.7 := TRUE;
            iState := 99;
        END_IF;


    30: (* --- 30: STATE_HYDRAULIC_PRIME --- *)
        (* Gentle displacement rotation to eliminate gas pockets in plunger cavities *)
        bSystemReady := TRUE;
        bFuelingActive := FALSE;
        rPumpDrive_SpeedCmd_rpm := PUMP_PRIME_SPEED_RPM; (* 60 RPM *)
        rVlv_SpillbackBypass_Pct := 80.0;
        rVlv_VaporReturn_Pct := 100.0;
        rVlv_DirectInjection_Pct := 0.0;
        rVlv_ColdVent_Pct := 0.0;

        tGeneralTimer(IN := TRUE, PT := T#15S);

        IF tGeneralTimer.Q THEN
            tGeneralTimer(IN := FALSE);
            IF (rPT_Disch_Voted_MPa >= 1.5) AND (rCavitationRiskFactor < 0.2) THEN
                iState := 40; (* Ready for Coupling Leak Pulse Test *)
            ELSE
                iState := 99; (* Prime failure or vapor lock *)
            END_IF;
        END_IF;


    40: (* --- 40: STATE_LEAK_PULSE_CHECK --- *)
        (* Injects a 5-MPa micro-pulse to verify hose, breakaway, and nozzle sealing *)
        bSystemReady := TRUE;
        bFuelingActive := FALSE;

        CASE iSubState OF
            0: (* Inject to 5 MPa *)
                rPumpDrive_SpeedCmd_rpm := 90.0;
                rVlv_SpillbackBypass_Pct := 20.0;
                rVlv_DirectInjection_Pct := 25.0;
                rVlv_ColdVent_Pct := 0.0;

                IF rPT_Disch_Voted_MPa >= LEAK_PULSE_TARGET_MPA THEN
                    rLeakCheckStartP_MPa := rPT_Disch_Voted_MPa;
                    rPumpDrive_SpeedCmd_rpm := 0.0;
                    rVlv_DirectInjection_Pct := 0.0;
                    rVlv_SpillbackBypass_Pct := 100.0;
                    tLeakHoldTimer(IN := TRUE, PT := T#15S);
                    iSubState := 1;
                END_IF;

            1: (* Dwell & Measure Pressure Decay Rate *)
                rPumpDrive_SpeedCmd_rpm := 0.0;
                rVlv_DirectInjection_Pct := 0.0;

                IF tLeakHoldTimer.Q THEN
                    tLeakHoldTimer(IN := FALSE);
                    rLeakCheckEndP_MPa := rPT_Disch_Voted_MPa;
                    rLeakDecayCalculated_MPamin := (rLeakCheckStartP_MPa - rLeakCheckEndP_MPa) * 4.0;

                    IF rLeakDecayCalculated_MPamin <= MAX_LEAK_DECAY_MPA_MIN THEN
                        bLeakCheckPassed := TRUE;
                        iState := 50; (* Success -> Proceed to 90-MPa Direct Injection Ramp *)
                        iSubState := 0;
                    ELSE
                        bLeakCheckPassed := FALSE;
                        wAlarmWord.1 := TRUE; (* Hose Leak Detected *)
                        iState := 80; (* Abort to Depressurization *)
                    END_IF;
                END_IF;
        END_CASE;


    50: (* --- 50: STATE_DIRECT_INJECTION_RAMP --- *)
        (* High-Speed Supercritical Injection adhering to SAE J2601-5 corridor *)
        bSystemReady := TRUE;
        bFuelingActive := TRUE;
        bFuelingComplete := FALSE;

        (* Dynamically throttle target ramp rate if vehicle tank temperature heats up *)
        IF rVehicleTankTemp_K > 340.0 THEN
            rDynamicRampCeiling_MPamin := MAX(5.0, rTargetRampRate_MPamin * ((T_VEHICLE_MAX_K - rVehicleTankTemp_K) / 18.15));
        ELSE
            rDynamicRampCeiling_MPamin := rTargetRampRate_MPamin;
        END_IF;

        (* Evaluate reference trajectory step *)
        rTargetTrajectory_MPa := MIN(P_TARGET_FINAL_MPA, 
                                     rPT_Disch_Voted_MPa + (rDynamicRampCeiling_MPamin / 60.0) * T_SCAN_S);

        (* Setup MPC Setpoint Target *)
        x_setpoint[0] := rTargetTrajectory_MPa;
        x_setpoint[1] := rDynamicRampCeiling_MPamin / 60.0;
        x_setpoint[2] := 235.0; (* Dispensing T40 Nominal Window (around -38 deg C) *)
        x_setpoint[3] := 180.0; (* Desired Dispensing Flow: 180 kg/h *)
        x_setpoint[4] := 100.0; (* 100% Target SOC *)

        (* Check Transition to Final 90-MPa Packing Mode *)
        IF rPT_Disch_Voted_MPa >= 87.500 THEN
            iState := 60; (* Switch to Fine Packing Trim *)
        END_IF;


    60: (* --- 60: STATE_TARGET_PACKING_TRIM --- *)
        (* Final Pressure Pack from 87.5 to 90.0 MPa with smooth mass flow taper *)
        bSystemReady := TRUE;
        bFuelingActive := TRUE;

        rTargetTrajectory_MPa := P_TARGET_FINAL_MPA;
        x_setpoint[0] := P_TARGET_FINAL_MPA;
        x_setpoint[1] := 1.0 / 60.0; (* Slow creep ramp *)
        x_setpoint[2] := 240.0;
        x_setpoint[3] := 45.0;  (* Tapered Flow *)
        x_setpoint[4] := 100.0;

        tGeneralTimer(IN := (rPT_Disch_Voted_MPa >= (P_TARGET_FINAL_MPA - 0.2)), PT := T#8S);

        IF tGeneralTimer.Q OR (rVehicleStateOfCharge_Pct >= 99.8) THEN
            tGeneralTimer(IN := FALSE);
            bFuelingComplete := TRUE;
            bFuelingActive := FALSE;
            iState := 70; (* Advance to Safe Disconnect Depressurization *)
        END_IF;


    70: (* --- 70: STATE_CYCLE_COMPLETION --- *)
        bSystemReady := FALSE;
        bFuelingActive := FALSE;
        bFuelingComplete := TRUE;
        rPumpDrive_SpeedCmd_rpm := 0.0;
        rVlv_DirectInjection_Pct := 0.0;
        rVlv_SpillbackBypass_Pct := 100.0; (* Flush pump cavity *)
        rVlv_VaporReturn_Pct := 100.0;

        tGeneralTimer(IN := TRUE, PT := T#5S);
        IF tGeneralTimer.Q THEN
            tGeneralTimer(IN := FALSE);
            iState := 80;
        END_IF;


    80: (* --- 80: STATE_DEPRESSURIZATION_VENT --- *)
        (* Vent locked line hydrogen between injection valve and breakaway to BOG/Vent *)
        bSystemReady := FALSE;
        bFuelingActive := FALSE;
        rPumpDrive_SpeedCmd_rpm := 0.0;
        rVlv_DirectInjection_Pct := 0.0;
        rVlv_SpillbackBypass_Pct := 100.0;
        rVlv_ColdVent_Pct := 35.0; (* Controlled vent orifice *)
        rVlv_VaporReturn_Pct := 100.0;

        tDepressTimer(IN := TRUE, PT := T#12S);

        IF (rPT_Disch_Voted_MPa <= 0.8) OR tDepressTimer.Q THEN
            tDepressTimer(IN := FALSE);
            rVlv_ColdVent_Pct := 0.0;
            IF bTripAlarm THEN
                iState := 99;
            ELSE
                iState := 0; (* Return to Standby *)
            END_IF;
        END_IF;


    99: (* --- 99: STATE_SAFETY_TRIP_EMERGENCY --- *)
        (* SIL-3 Lockout: Kill VFD, Slam Emergency Isolation Valves, Vent Trapped Fluid *)
        bSystemReady := FALSE;
        bFuelingActive := FALSE;
        bFuelingComplete := FALSE;
        rPumpDrive_SpeedCmd_rpm := 0.0;
        rVlv_DirectInjection_Pct := 0.0;
        rVlv_SpillbackBypass_Pct := 0.0;
        rVlv_ColdVent_Pct := 100.0;        (* Immediate High-Pressure Blowdown *)
        rVlv_VaporReturn_Pct := 0.0;

        (* Reset Permissive only when alarms cleared and manual reset applied *)
        IF (NOT bTripAlarm) AND (NOT bEnable) THEN
            rVlv_ColdVent_Pct := 0.0;
            iState := 0;
        END_IF;

END_CASE;

(*
 * =========================================================================================
 * 7.0 DISCRETE LUENBERGER OBSERVER UPDATE EQUATIONS
 * =========================================================================================
 * Measurement Innovation: y_innov = y_meas - C * x_pred
 * State Estimate: x_hat = x_pred + L * y_innov
 * Prediction: x_pred = A * x_hat + B * u
 *)
y_innov[0] := rPT_Disch_Voted_MPa - x_pred[0];
y_innov[1] := (rActualRampRate_MPamin / 60.0) - x_pred[1];
y_innov[2] := rTT_ColdEnd_Voted_K - x_pred[2];
y_innov[3] := rMassFlow_Filt_kgh_Int - x_pred[3];
y_innov[4] := rVehicleStateOfCharge_Pct - x_pred[4];

(* Observer State Correction *)
FOR iRow := 0 TO 4 DO
    x_hat[iRow] := x_pred[iRow];
    FOR iCol := 0 TO 4 DO
        x_hat[iRow] := x_hat[iRow] + L_obs[iRow, iCol] * y_innov[iCol];
    END_FOR;
END_FOR;

(*
 * =========================================================================================
 * 8.0 CONSTRAINED MODEL PREDICTIVE CONTROL (MPC) & HILDRETH QP SOLVER
 * =========================================================================================
 * Executed during active ramp (State 50 and 60). Calculates constrained optimal inputs:
 * u1 = Pump VFD RPM [0..450], u2 = Spillback Bypass [0..100%], u3 = Direct Inj Valve [0..100%]
 *)
IF (iState = 50) OR (iState = 60) THEN

    (* Calculate Linear Gradient Vector: g = B^T * Q * (x_hat - x_setpoint) *)
    FOR iRow := 0 TO 2 DO
        g_grad[iRow] := 0.0;
        FOR kIdx := 0 TO 4 DO
            g_grad[iRow] := g_grad[iRow] + B_sys[kIdx, iRow] * Q_diag[kIdx] * (x_hat[kIdx] - x_setpoint[kIdx]);
        END_FOR;
    END_FOR;

    (* Unconstrained Newton Step: delta_u = - H^-1 * g *)
    FOR iRow := 0 TO 2 DO
        delta_u[iRow] := 0.0;
        FOR iCol := 0 TO 2 DO
            delta_u[iRow] := delta_u[iRow] - H_inv[iRow, iCol] * g_grad[iCol];
        END_FOR;
    END_FOR;

    (* Preliminary Candidate Demands *)
    u_opt[0] := u_prev[0] + delta_u[0];
    u_opt[1] := u_prev[1] + delta_u[1];
    u_opt[2] := u_prev[2] + delta_u[2];

    (* Hildreth Dual Active-Set Box Projection *)
    FOR iQP_Iter := 1 TO 6 DO
        (* Clamp Actuator 0: Pump VFD RPM [30.0 .. 450.0] *)
        IF u_opt[0] < PUMP_MIN_SPEED_RPM THEN
            u_opt[0] := PUMP_MIN_SPEED_RPM;
        ELSIF u_opt[0] > PUMP_MAX_SPEED_RPM THEN
            u_opt[0] := PUMP_MAX_SPEED_RPM;
        END_IF;

        (* Clamp Actuator 1: Spillback Valve [0.0 .. 100.0] *)
        IF u_opt[1] < 0.0 THEN
            u_opt[1] := 0.0;
        ELSIF u_opt[1] > 100.0 THEN
            u_opt[1] := 100.0;
        END_IF;

        (* Clamp Actuator 2: Direct Injection Valve [0.0 .. 100.0] *)
        IF u_opt[2] < 0.0 THEN
            u_opt[2] := 0.0;
        ELSIF u_opt[2] > 100.0 THEN
            u_opt[2] := 100.0;
        END_IF;
    END_FOR;

    (* Assign Calculated Control Outputs *)
    rPumpDrive_SpeedCmd_rpm := u_opt[0];
    rVlv_SpillbackBypass_Pct := u_opt[1];
    rVlv_DirectInjection_Pct := u_opt[2];

    (* Save State for Slew Rate Penalization *)
    u_prev[0] := u_opt[0];
    u_prev[1] := u_opt[1];
    u_prev[2] := u_opt[2];

ELSE
    (* Retain Passive Internal Memory *)
    u_prev[0] := rPumpDrive_SpeedCmd_rpm;
    u_prev[1] := rVlv_SpillbackBypass_Pct;
    u_prev[2] := rVlv_DirectInjection_Pct;
END_IF;

(* Observer Time-Update Propagation: x_pred = A * x_hat + B * u *)
FOR iRow := 0 TO 4 DO
    x_pred[iRow] := 0.0;
    FOR iCol := 0 TO 4 DO
        x_pred[iRow] := x_pred[iRow] + A_sys[iRow, iCol] * x_hat[iCol];
    END_FOR;
    x_pred[iRow] := x_pred[iRow] + B_sys[iRow, 0] * u_prev[0] 
                                 + B_sys[iRow, 1] * u_prev[1] 
                                 + B_sys[iRow, 2] * u_prev[2];
END_FOR;

(*
 * =========================================================================================
 * 9.0 MASTER SYSTEM STATUS & DIAGNOSTIC WORD ENCODING
 * =========================================================================================
 *)
wStatusWord.0 := bEnable;
wStatusWord.1 := bSystemReady;
wStatusWord.2 := bFuelingActive;
wStatusWord.3 := bFuelingComplete;
wStatusWord.4 := bSubcoolingConfirmed;
wStatusWord.5 := bLeakCheckPassed;
wStatusWord.6 := bTripAlarm;
wStatusWord.7 := bDegradedMode;
wStatusWord.8 := (iState = 20); (* Chilldown Active *)
wStatusWord.9 := (iState = 50); (* 90-MPa Fast Ramp Active *)
wStatusWord.10 := (iState = 60); (* 90-MPa Packing Active *)
wStatusWord.11 := (iState = 80); (* Depressurizing *)
wStatusWord.12 := (rCavitationRiskFactor > 0.5); (* Cavitation Warning *)

iActiveStateCode := iState;

END_FUNCTION_BLOCK
